/**
 * Generates SEMANTICS.md from semantics.json.
 *
 * semantics.json is the single source of truth; this script only renders it.
 * The generated file is committed, and tests/semantics.test.js fails if the
 * two drift - the same arrangement as `website/`, generated by freeze.py and
 * checked by diffing the freeze.
 *
 *   node scripts/gen-semantics.mjs            write SEMANTICS.md
 *   node scripts/gen-semantics.mjs --check    exit 1 if it would change
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const DATA = join(root, 'semantics.json');
const OUT = join(root, 'SEMANTICS.md');

const esc = (s) => String(s).replace(/\|/g, '\\|');
// Table cells too: a selector containing `|` (an attribute namespace, say)
// would otherwise split the row.
const code = (s) => '`' + esc(String(s).replace(/`/g, '\\`')) + '`';

export function render(data) {
  const names = Object.keys(data.components).sort();
  const enforced = names.filter((n) => data.components[n].status === 'enforced');
  const exempt = names.filter((n) => data.components[n].status !== 'enforced');

  const l = [];
  l.push('# HTML semantics');
  l.push('');
  l.push('<!-- Generated by scripts/gen-semantics.mjs from semantics.json. Do not edit. -->');
  l.push('');
  l.push(data.about);
  l.push('');
  l.push('## Rules');
  l.push('');
  l.push(data.scope);
  l.push('');
  data.rules.forEach((r, i) => l.push(`${i + 1}. ${r}`));
  l.push('');
  l.push('## Enforcement');
  l.push('');
  l.push('`tests/semantics.test.js` runs every rule below against three surfaces:');
  l.push(data.surfaces.map((s) => `${code(s)}`).join(', ') + '.');
  l.push('');
  l.push('A rule runs only when its component is **enforced**. An **exempt** component');
  l.push('has not been swept yet; the exempt list only ever shrinks, and a component');
  l.push('added to the framework starts enforced. An individual example may opt out with');
  l.push('a reason - ```` ```html ignore-semantics: why ```` in Markdown, or');
  l.push(code('code(check=false, reason="why")') + ' in a docs template.');
  l.push('');
  l.push(`**${enforced.length} of ${names.length} components enforced; ${exempt.length} remaining.**`);
  l.push('');
  const indebted = names.filter((n) => data.components[n].conformance);
  l.push('**Conformance debt** is a separate axis from enforced/exempt: a fully enforced');
  l.push('component may still withhold a composite role because the keyboard contract rule 2');
  l.push('demands does not exist yet. Each one below names the role it withholds, what that');
  l.push('waits on, and the rule that keeps the role out of markup meanwhile.');
  l.push('');
  l.push('A component may also *reject* a role: one it will never take because it implements a');
  l.push('different pattern. That is not debt - the code is not behind, it went another way - and');
  l.push('the same rule-linking applies, so neither can be recorded without enforcement.');
  l.push('');
  l.push('The composite roles that can be withheld or rejected: ' + data.compositeRoles.map(code).join(', ') + '.');
  l.push('');
  const declares = indebted.length === 1 ? 'declares' : 'declare';
  l.push(`**${indebted.length} of ${names.length} components ${declares} conformance debt.**`);
  l.push('');
  l.push('That is a count of *declarations*, not of debt. The suite pairs a declaration with a');
  l.push('rule and a role-blocking rule with a declaration, so neither can exist alone - but a');
  l.push('role withheld by convention, with no rule behind it, is invisible to it.');
  l.push('');

  l.push('## Enforced');
  l.push('');
  for (const name of enforced) l.push(...renderComponent(name, data.components[name]));

  l.push('## Exempt');
  l.push('');
  l.push('Not yet swept. Rules listed here are recorded but do not run.');
  l.push('');
  l.push('| Component | Rules written | Note |');
  l.push('| --- | --- | --- |');
  for (const name of exempt) {
    const c = data.components[name];
    l.push(`| ${code(name)} | ${c.rules.length} | ${esc(c.note ?? '')} |`);
  }
  l.push('');
  return l.join('\n') + '\n';
}

/** Whether the rule a declaration names keeps every composite role out, not just the declared one. */
function blocksEveryRole(c, rule) {
  return c.rules.some((r) => r.id === rule && r.kind === 'forbid-composite-roles');
}

function renderComponent(name, c) {
  const l = [`### ${name}`, ''];
  if (c.note) l.push(c.note, '');
  if (c.conformance) {
    const { withheld_role: role, blocked_on: blocked, rule } = c.conformance;
    l.push(
      `**Conformance debt:** ${code(role)} is withheld pending ${esc(blocked)}, ` +
        `and ${code(rule)} enforces that` +
        (blocksEveryRole(c, rule) ? ', keeping every composite role out.' : '.'),
      ''
    );
  }
  if (c.rejects) {
    const { rejected_role: role, because, rule } = c.rejects;
    l.push(
      `**Rejected role:** ${code(role)} is not withheld but declined - ${esc(because)}. ` +
        `${code(rule)} enforces that` +
        (blocksEveryRole(c, rule) ? ', keeping every composite role out.' : '.'),
      ''
    );
  }
  l.push('| Rule | Kind | Selector | Requirement |');
  l.push('| --- | --- | --- | --- |');
  for (const r of c.rules) {
    const req =
      r.kind === 'forbid'
        ? 'must not match'
        : r.kind === 'forbid-composite-roles'
          ? 'must not match with any composite role'
          : r.kind === 'require-accessible-name'
            ? 'must end up with an accessible name'
            : `must have ${code(r.attr)}` + (r.equals ? ` = ${code(r.equals)}` : '');
    l.push(`| ${code(r.id)} | ${r.kind} | ${code(r.selector)} | ${req} |`);
  }
  l.push('');
  for (const r of c.rules) l.push(`- **${r.id}** - ${r.message}`);
  l.push('');
  return l;
}

// Only when run as a command. Without this guard, `import { render }` from the
// test would rewrite SEMANTICS.md on import - and the drift test would then
// compare the file against the copy it had just written, and always pass.
const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  const out = render(JSON.parse(readFileSync(DATA, 'utf8')));
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(OUT, 'utf8');
    } catch {
      /* missing counts as drift */
    }
    if (current !== out) {
      console.error('SEMANTICS.md is stale. Run: npm run build:semantics');
      process.exit(1);
    }
    console.log('SEMANTICS.md is up to date.');
  } else {
    writeFileSync(OUT, out);
    console.log(`Wrote ${OUT}`);
  }
}
